// 无限滚动：多页乱序到达，按页序合并并去重
function mergePages(pages) {
  const byIndex = [...pages].sort((a, b) => a.pageIndex - b.pageIndex);
  const seen = new Set();
  const out = [];
  for (const p of byIndex) {
    for (const it of p.items) {
      if (seen.has(it.id)) continue;
      seen.add(it.id);
      out.push(it);
    }
  }
  return out;
}
const ids = arr => arr.map(x => x.id).join(',');

const p1 = { pageIndex: 0, items: [{ id: 1 }, { id: 2 }] };
const p2 = { pageIndex: 1, items: [{ id: 3 }, { id: 4 }] };
const p3 = { pageIndex: 2, items: [{ id: 5 }] };

const inOrder = mergePages([p1, p2, p3]);
const outOfOrder = mergePages([p3, p1, p2]);
const withDup = mergePages([p1, { pageIndex: 1, items: [{ id: 2 }, { id: 3 }] }, p3]);

console.log('in_order_ids=' + ids(inOrder));
console.log('out_of_order_ids=' + ids(outOfOrder));
console.log('order_stable=' + (ids(inOrder) === ids(outOfOrder)));
console.log('dup_merged_ids=' + ids(withDup));
console.log('merged_count=' + withDup.length);
console.log('raw_count=' + (2 + 2 + 1));
console.log('duplicates_removed=' + (5 - withDup.length));
console.log('no_duplicate_ids=' + (new Set(withDup.map(x => x.id)).size === withDup.length));
